using System;
using System.Collections.Generic;
using Unity.Entities;
using Unity.Mathematics;
using UnityEngine;

namespace ToLive.Destruction
{
    /// <summary>
    /// Root of the pre-fractured building (generated by Tools > To Live > Make Breakable Building).
    /// Holds the chunk graph used for structural support: which chunks touch which, and which
    /// stand on the ground. The chunks themselves are child objects with <see cref="ChunkAuthoring"/>.
    /// </summary>
    [DisallowMultipleComponent]
    public class BreakableBuildingAuthoring : MonoBehaviour
    {
        [Serializable]
        public struct ChunkData
        {
            public Vector3 Center;
            public Vector3 Size;
            public bool Grounded;
            public int[] Neighbors;
        }

        public List<ChunkData> Chunks = new List<ChunkData>();

        class Baker : Baker<BreakableBuildingAuthoring>
        {
            public override void Bake(BreakableBuildingAuthoring authoring)
            {
                var entity = GetEntity(TransformUsageFlags.None);
                var center = float3.zero;
                foreach (var c in authoring.Chunks) center += (float3)c.Center;
                if (authoring.Chunks.Count > 0) center /= authoring.Chunks.Count;
                AddComponent(entity, new BuildingGraph { ChunkCount = authoring.Chunks.Count, Center = center });

                var nodes = AddBuffer<ChunkNode>(entity);
                var neighbors = AddBuffer<ChunkNeighbor>(entity);
                foreach (var c in authoring.Chunks)
                {
                    var n = c.Neighbors ?? Array.Empty<int>();
                    nodes.Add(new ChunkNode
                    {
                        Center = c.Center, Size = c.Size, Grounded = (byte)(c.Grounded ? 1 : 0),
                        NeighborStart = neighbors.Length, NeighborCount = n.Length,
                    });
                    foreach (var i in n) neighbors.Add(new ChunkNeighbor { Index = i });
                }
                AddBuffer<BreakRequest>(entity);
                AddBuffer<DebrisSpawnRequest>(entity);
                AddComponent<BuildingCommand>(entity);
                AddComponent<BuildingApplied>(entity);
            }
        }
    }
}
